/**
 * Whole-India railway network, split into 5 importance tiers that are loaded
 * lazily and revealed as the map zooms in.
 *
 *   tier 1  Trunk     longest / busiest lines + the named corridors
 *   tier 2  Main
 *   tier 3  Regional
 *   tier 4  Branch
 *   tier 5  Local     everything else, incl. metre / narrow gauge
 *
 * The data is generated by tools/railtracks/build_network.py from real
 * OpenStreetMap-derived track geometry. Each tier file is a list of "pieces"
 * (≤ ~80 vertices each, so the map can cull them cheaply):
 *   [stateIdx, gaugeIdx, nameIdx, corridorIdxs[], fineFlat, coarseFlat?]
 * with coordinates delta-encoded as integers at `meta.scale` per degree.
 */
import META from '@/data/railNetwork/meta.json'

export const TIERS = META.tiers // [{ id, name, minZoom, pieces, km }]
export const TIER_COUNT = TIERS.length
export const CORRIDOR_IDS = META.corridors.map((c) => c.id)
export const CORRIDOR_NAMES = META.corridors.map((c) => c.name)

// Risk ranks (kept identical to SEVERITY_RANK in IndiaRailwayMap)
export const RISK_KEYS = [null, 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL']
export const RISK_RANK = { LOW: 1, MEDIUM: 2, HIGH: 3, CRITICAL: 4 }

// Tracks within this many km of an open issue inherit its severity.
export const ISSUE_RADIUS_KM = { CRITICAL: 90, HIGH: 60, MEDIUM: 35 }

/** Highest tier that should be visible at a given (possibly fractional) zoom. */
export function tierForZoom(zoom) {
  let t = 1
  for (const tier of TIERS) if (zoom >= tier.minZoom - 1e-6) t = tier.id
  return t
}

/** Zoom at/below which the simplified ("coarse") copy of tiers 1-2 is drawn. */
export const COARSE_MAX_ZOOM = 7

export function totalKm(maxTier) {
  return TIERS.filter((t) => t.id <= maxTier).reduce((s, t) => s + t.km, 0)
}
export const NETWORK_KM = totalKm(TIER_COUNT)

// ---------------------------------------------------------------- loading ---

const LOADERS = {
  1: () => import('@/data/railNetwork/tier1.json'),
  2: () => import('@/data/railNetwork/tier2.json'),
  3: () => import('@/data/railNetwork/tier3.json'),
  4: () => import('@/data/railNetwork/tier4.json'),
  5: () => import('@/data/railNetwork/tier5.json'),
}
const cache = new Map() // tier -> Promise<piece[]>

export function loadTier(tier) {
  if (!cache.has(tier)) {
    const p = LOADERS[tier]()
      .then((m) => decodeTier(tier, m.default ?? m))
      .catch((err) => {
        cache.delete(tier) // allow a retry later
        throw err
      })
    cache.set(tier, p)
  }
  return cache.get(tier)
}

// --------------------------------------------------------------- decoding ---

const RAD = Math.PI / 180

function decodeGeom(flat) {
  const Q = META.scale
  const n = flat.length >> 1
  const mx = new Float64Array(n) // web-mercator, normalised to 0..1
  const my = new Float64Array(n)
  const lat = new Float32Array(n)
  const lng = new Float32Array(n)
  let la = 0
  let lo = 0
  let km = 0
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity
  for (let i = 0; i < n; i++) {
    la += flat[2 * i]
    lo += flat[2 * i + 1]
    const a = la / Q
    const o = lo / Q
    lat[i] = a
    lng[i] = o
    const x = (o + 180) / 360
    const s = Math.sin(a * RAD)
    const y = 0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)
    mx[i] = x
    my[i] = y
    if (x < x0) x0 = x
    if (x > x1) x1 = x
    if (y < y0) y0 = y
    if (y > y1) y1 = y
    if (i > 0) {
      const dx = (o - lng[i - 1]) * 111.32 * Math.cos(a * RAD)
      const dy = (a - lat[i - 1]) * 110.57
      km += Math.hypot(dx, dy)
    }
  }
  return { n, mx, my, lat, lng, km, x0, y0, x1, y1 }
}

/** Urban metro / monorail / MRTS lines are not part of the mainline network shown here. */
export const METRO_NAME_RE = /metro|monorail|mrts/i

function decodeTier(tier, records) {
  const out = []
  for (let i = 0; i < records.length; i++) {
    const [st, ga, nm, cors, fineFlat, coarseFlat] = records[i]
    if (METRO_NAME_RE.test(META.names[nm] || '')) continue
    const fine = decodeGeom(fineFlat)
    out.push({
      tier,
      state: META.states[st] || '',
      gauge: META.gauges[ga] || META.gauges[0],
      name: META.names[nm] || '',
      cors, // indices into CORRIDOR_IDS
      fine,
      coarse: coarseFlat ? decodeGeom(coarseFlat) : null,
      risk: 1, // set by applyRisk()
    })
  }
  return out
}

// ------------------------------------------------------------------- risk ---

/**
 * Colour every piece by risk priority.
 *
 *  - corridorRank: { [corridorId]: 1..4 }  (existing station→corridor model)
 *  - sites: [{ lat, lng, rank }]           (open issues, rank 2..4)
 *
 * A piece takes the highest of: the risk of any named corridor it belongs to,
 * and the severity of any open issue within ISSUE_RADIUS_KM of it.
 */
export function applyRisk(pieces, corridorRank = {}, sites = []) {
  const corRank = CORRIDOR_IDS.map((id) => corridorRank[id] || 1)
  const circles = sites
    .filter((s) => s.rank >= 2)
    .map((s) => {
      const key = RISK_KEYS[s.rank]
      const r = ISSUE_RADIUS_KM[key] || 0
      const kx = 111.32 * Math.cos(s.lat * RAD)
      return { ...s, r, dLat: r / 110.57, dLng: r / kx, kx }
    })

  for (const p of pieces) {
    let rank = 1
    for (const ci of p.cors) if (corRank[ci] > rank) rank = corRank[ci]

    if (rank < 4) {
      for (const c of circles) {
        if (c.rank <= rank) continue
        if (!pieceNear(p.fine, c)) continue
        rank = c.rank
        if (rank === 4) break
      }
    }
    p.risk = rank
  }
}

function pieceNear(g, c) {
  // cheap reject on the lat/lng box, then walk vertices
  let hit = false
  const { lat, lng, n } = g
  for (let i = 0; i < n; i++) {
    const dLat = lat[i] - c.lat
    if (dLat > c.dLat || dLat < -c.dLat) continue
    const dLng = lng[i] - c.lng
    if (dLng > c.dLng || dLng < -c.dLng) continue
    const dx = dLng * c.kx
    const dy = dLat * 110.57
    if (dx * dx + dy * dy <= c.r * c.r) {
      hit = true
      break
    }
  }
  return hit
}
